fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and choose the 'Permissions' application; it opens on the 'User Access' tab in the left nav. Then perform these sub-actions IN ORDER, and as you complete each set \"checkpointReached\" to the exact checkpoint name shown: (1) access-report-loads — confirm the 'User Access Report' surface renders: a 'User:' picker dropdown at top (pre-selected to a user, since the current user is auto-selected on load) and either a 'N permissions across M domains' summary with collapsible domain accordion panels below, OR a clear empty-state card; (2) access-switch-user — open the 'User:' dropdown and select a DIFFERENT user, and confirm the report responds (a brief 'Loading permissions...' state may appear, then the domain groups / summary count update for the newly selected user, or a valid 'No permissions' empty-state); (3) access-domain-expand — find a collapsible domain accordion panel (domain name + icon + count badge); if the pre-selected user shows no domains, pick a user with permissions (an admin user is a good bet); click a panel header to expand it and confirm it reveals a permissions table with Resource / Type / Actions / Effect (Allow/Deny) columns, then click again to collapse it (a valid 'No permissions' empty-state is an acceptable success if the user genuinely has none). Keep going until all sub-actions are done. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/permissions",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "access-report-loads",
      "instruction": "User Access Report renders for the auto-selected user",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/permissions"
        }
      ],
      "visualCriteria": [
        "The User Access Report renders with a 'User:' selector dropdown at the top, a user pre-selected, and either a '...permissions across ...domains' summary with domain accordion panels OR a clearly labeled empty-state card"
      ]
    },
    {
      "name": "access-switch-user",
      "instruction": "select a different user and see the report reload",
      "visualCriteria": [
        "Selecting a different user in the 'User:' dropdown triggers a reload (loading indicator and/or updated summary/accordion content) and the report content reflects the newly selected user — either updated permission domain groups OR a valid 'No permissions' empty-state"
      ]
    },
    {
      "name": "access-domain-expand",
      "instruction": "expand/collapse a domain accordion panel to reveal its permissions table",
      "visualCriteria": [
        "A domain accordion panel with a name, icon, and count badge is visible, and clicking its header expands it to show a permissions table (Resource / Type / Actions / Effect columns) that can be collapsed again — or a valid 'No permissions' empty-state is shown"
      ]
    }
  ]
}
